<script setup lang="ts">
import {ref,onMounted,onUnmounted,nextTick} from 'vue'
import {X,RefreshCw} from 'lucide-vue-next'
import {api,cents,money,key,type Wagering} from '../api/account'
const props=defineProps<{member:{id:string;username:string}}>()
const emit=defineEmits<{close:[];saved:[];notify:[message:string]}>()
const progress=ref<Wagering|null>(null),amount=ref(''),green=ref(false),note=ref(''),error=ref(''),loading=ref(false),saving=ref(false),requestKey=ref(key()),dialog=ref<HTMLElement|null>(null)
let active=true,previousFocus:HTMLElement|null=null
async function load(){loading.value=true;error.value='';try{const next=await api<Wagering>(`/admin/users/${props.member.id}/wagering`);if(active){progress.value=next;amount.value=(next.turnover_cents/100).toFixed(2);green.value=next.green_channel;note.value='';requestKey.value=key()}}catch(e){if(active)error.value=(e as Error).message}finally{if(active)loading.value=false}}
async function save(){if(!progress.value||saving.value)return;saving.value=true;error.value='';try{await api(`/admin/users/${props.member.id}/wagering`,'POST',{version:progress.value.version,revision:progress.value.revision,turnover_cents:cents(amount.value),green_channel:green.value,note:note.value.trim(),key:requestKey.value});emit('notify','打码量与绿色通道已更新，已记录操作日志');emit('saved');emit('close')}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
function close(){if(!saving.value)emit('close')}
function trap(e:KeyboardEvent){if(e.key!=='Tab')return;const els=dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled)');if(!els?.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog.value)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
onMounted(async()=>{previousFocus=document.activeElement as HTMLElement;await nextTick();dialog.value?.focus();void load()})
onUnmounted(()=>{active=false;previousFocus?.focus()})
</script>
<template><div class="modal-overlay" @click.self="close" @keydown.esc="close" @keydown="trap"><section ref="dialog" class="modal wager-editor" role="dialog" aria-modal="true" aria-labelledby="wager-editor-title" tabindex="-1"><button class="modal-close icon-button" :disabled="saving" aria-label="关闭打码设置" @click="close"><X/></button><h2 id="wager-editor-title">打码设置 · {{member.username}}</h2><p v-if="error" class="form-error" role="alert">{{error}}</p><button class="text-button" :disabled="loading||saving" @click="load"><RefreshCw :size="14"/>重新读取</button><p v-if="loading" class="loading-line">读取打码进度…</p><form v-if="progress" class="form-stack" @submit.prevent="save"><div class="wager-summary"><p>打码额度 <strong>{{money(progress.required_cents)}} 元</strong></p><p>充值 {{money(progress.deposit_cents)}} 元＋奖励 {{money(progress.reward_cents)}} 元</p><p>当前打码量 {{money(progress.turnover_cents)}} 元</p></div><label>调整后打码量（元）<input v-model="amount" :disabled="saving||loading" required inputmode="decimal"/></label><label class="wager-green"><input v-model="green" type="checkbox" :disabled="saving||loading"/>绿色通道：豁免打码限制</label><label>调整原因<textarea v-model="note" :disabled="saving||loading" required minlength="2" maxlength="500" rows="3"/></label><p class="form-hint">仅调整打码量与豁免状态，不改变账户余额、下注或充值原始记录。绿色通道不免除提现手续费。</p><button class="primary-button" :disabled="saving||loading">{{saving?'保存中…':'保存并记录操作'}}</button></form></section></div></template>
<style scoped>.wager-editor{text-align:left;max-height:90dvh;overflow:auto}.wager-editor h2{font-size:21px;padding-right:20px;overflow-wrap:anywhere}.wager-editor .text-button{display:flex;gap:6px;margin:16px 0}.wager-summary{background:#faf7ff;padding:12px;font-size:13px;line-height:1.8}.wager-summary p{margin:4px 0}.wager-green{display:flex!important;align-items:center;gap:8px}.wager-green input{width:17px!important;height:17px}.wager-editor .form-hint{line-height:1.8}</style>
